'use strict';
const chapters=window.GUIDE.chapters;
const lessons=chapters.flatMap((c,ci)=>c.lessons.map((s,si)=>({...s,chapter:c.title,chapterIndex:ci,inChapter:si+1,chapterLength:c.lessons.length})));
const $=id=>document.getElementById(id);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const macros={'\\E':'\\mathbb{E}','\\Var':'\\operatorname{Var}','\\Cov':'\\operatorname{Cov}','\\one':'\\mathbf{1}','\\F':'\\mathcal{F}','\\G':'\\mathcal{G}','\\HH':'\\mathcal{H}','\\R':'\\mathbb{R}'};
function math(s,display){try{return window.katex.renderToString(s,{displayMode:display,throwOnError:true,macros,strict:'ignore',trust:false,output:'htmlAndMathml'});}catch(e){console.error('Math rendering failed',s,e);return escapeHTML(s);}}
function rich(text){return String(text).split(/\n\s*\n/).map(paragraph=>'<div class="prose">'+paragraph.split(/(\\\[[\s\S]*?\\\]|\$[^$]+\$)/g).map(part=>part.startsWith('\\[')?'<div class="math-display" tabindex="0" aria-label="Mathematical expression">'+math(part.slice(2,-2),true)+'</div>':part.startsWith('$')?'<span class="inline-math">'+math(part.slice(1,-1),false)+'</span>':escapeHTML(part)).join('')+'</div>').join('');}
let current=0;
const sizes=[14,16,18,20,22,24,26,28,30,32,36,40];
let sizeIndex=sizes.indexOf(24);
try{const saved=Number(localStorage.getItem('tina-text-pixels'));if(sizes.includes(saved))sizeIndex=sizes.indexOf(saved);else{const old=localStorage.getItem('tina-text-size');if(old!==null&&[0,1,2,3,4].includes(Number(old)))sizeIndex=sizes.indexOf([20,22,24,28,32][Number(old)]);}}catch(e){}
$('font-size').innerHTML=sizes.map(size=>'<option value="'+size+'">'+size+' px</option>').join('');
function updateSize(){const size=sizes[sizeIndex];document.documentElement.style.fontSize=size+'px';document.documentElement.classList.toggle('extra-large',size>=32);$('font-size').value=String(size);$('font-down').disabled=sizeIndex===0;$('font-up').disabled=sizeIndex===sizes.length-1;try{localStorage.setItem('tina-text-pixels',size);}catch(e){}}
function detailed(s){if(!s.details)return '';return '<details class="derivation" open><summary>Why this is true <span>'+s.details.length+' detailed steps</span></summary><ol class="derivation-steps">'+s.details.map(x=>'<li><h3>'+escapeHTML(x.title)+'</h3>'+rich(x.body)+'</li>').join('')+'</ol></details>';}
function closeMenu(){const wasOpen=$('navigation').classList.contains('open');$('navigation').classList.remove('open');$('menu-toggle').setAttribute('aria-expanded','false');if(wasOpen)$('menu-toggle').focus();}
function renderNav(){let n=0;$('navigation').innerHTML='<button class="nav-close" id="nav-close">Close contents ×</button><p class="nav-title">READING PATH</p>'+chapters.map((c,ci)=>'<details data-chapter="'+ci+'"><summary>'+escapeHTML(c.title)+'<span>'+c.lessons.length+' steps</span></summary><ol>'+c.lessons.map(s=>{const i=n++;return '<li><a href="#'+encodeURIComponent(s.id)+'" data-step="'+i+'">'+escapeHTML(s.title)+'</a></li>';}).join('')+'</ol></details>').join('')+'<div class="resources"><a href="paper.pdf" target="_blank" rel="noopener">Read the six-page paper ↗</a><a href="proof-report.pdf" target="_blank" rel="noopener">Full proof report ↗</a><a href="https://github.com/ANRGUSC/TINA/tree/main/papers/lcss" target="_blank" rel="noopener">Manuscript &amp; simulations ↗</a><a href="https://github.com/ANRGUSC/TINA/tree/main/explainers/lcss-letter" target="_blank" rel="noopener">Guide source &amp; corrections ↗</a><a href="https://github.com/ANRGUSC/TINA/tree/61f68b2b4c9340df44d3ee5bbc56d8fad9e5b6c3/papers/lcss" target="_blank" rel="noopener">Explained manuscript: 61f68b2 ↗</a></div>';$('nav-close').onclick=closeMenu;}
function show(index,focus=false){current=Math.max(0,Math.min(lessons.length-1,index));const s=lessons[current];document.title=s.title+' · TINA Reading Guide';$('lesson').innerHTML='<div class="lesson-head"><p class="eyebrow">'+escapeHTML(s.chapter)+' · '+s.inChapter+' / '+s.chapterLength+'</p><p class="paper-link"><a href="paper.pdf" target="_blank" rel="noopener">Read the L-CSS submission explained here (PDF) ↗</a></p><h1>'+escapeHTML(s.title)+'</h1><p class="lesson-source">'+escapeHTML(s.source||'Reading guide')+'</p></div><div class="reading-grid"><section class="math-panel" aria-label="Notation and mathematics">'+rich(s.body)+(s.image?'<img class="figure" src="'+escapeHTML(s.image)+'" alt="'+escapeHTML(s.alt)+'">':'')+detailed(s)+'</section><aside class="explanation" aria-label="Plain-English explanation"><h2>In plain English</h2>'+s.explain.map(p=>'<div class="explanation-paragraph">'+rich(p)+'</div>').join('')+(s.remember?'<div class="context-box">'+rich(s.remember)+'</div>':'')+'</aside></div>';$('back').disabled=current===0;$('next').disabled=current===lessons.length-1;$('position').innerHTML='<strong>Step '+(current+1)+' of '+lessons.length+'</strong><div class="progress-track" aria-hidden="true"><div class="progress-fill" style="width:'+((current+1)/lessons.length*100)+'%"></div></div>';document.querySelectorAll('nav [data-step]').forEach(a=>{if(Number(a.dataset.step)===current)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current');});document.querySelectorAll('nav details').forEach(d=>d.open=Number(d.dataset.chapter)===s.chapterIndex);closeMenu();if(focus){$('lesson').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function fromHash(){let id;try{id=decodeURIComponent(location.hash.slice(1));}catch(e){id='';}let i=lessons.findIndex(s=>s.id===id);show(i<0?0:i,true);}
function go(i){if(i<0||i>=lessons.length)return;location.hash=lessons[i].id;}
$('font-size').onchange=()=>{sizeIndex=sizes.indexOf(Number($('font-size').value));updateSize();};
$('back').onclick=()=>go(current-1);$('next').onclick=()=>go(current+1);$('font-up').onclick=()=>{sizeIndex=Math.min(sizes.length-1,sizeIndex+1);updateSize();};$('font-down').onclick=()=>{sizeIndex=Math.max(0,sizeIndex-1);updateSize();};$('menu-toggle').onclick=()=>{const open=$('navigation').classList.toggle('open');$('menu-toggle').setAttribute('aria-expanded',String(open));if(open)$('nav-close').focus();};
window.addEventListener('hashchange',fromHash);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();return;}if($('navigation').classList.contains('open')){if(e.key==='Tab'){const items=[...$('navigation').querySelectorAll('button,summary,a')].filter(x=>x.getClientRects().length);const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(document.activeElement.classList.contains('math-display')||e.altKey||e.ctrlKey||e.metaKey||e.shiftKey||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();go(current+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(current-1);}});
$('navigation').addEventListener('click',e=>{const a=e.target.closest('a[data-step]');if(a&&Number(a.dataset.step)===current){e.preventDefault();show(current,true);}});
renderNav();updateSize();fromHash();
